	"lder); }\n  });\n});\n\n/* --- go ----------------------------------------------------------------- */\n\n"
	"fetch(\"hostname\", { cache: \"no-store\" })\n  .then(function (res) { return res.ok \? res.text() : \"\"; }"
	")\n  .then(function (name) {\n    deviceName = (name || \"\").trim().toUpperCase();\n    if (deviceName) "
	"{ draw(); } // the title and the first crumb are its name\n  })\n  .catch(function () { /* the name is"
	" decoration; the page works without it */ });\n\nupdateHiddenButton();\nload(CARD);\n</script>\n</body>\n<"
	"/html>\n";

#endif /* WEBPAGE_H */
